# New approach: find rectangles where corners and at least some border exist
# A "frame" in ARC puzzles often has corners that define the rectangle,
# even if not all border cells are present

def find_partial_frame(grid, color):
    """Find all rectangles where corners (and maybe more) are present."""
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    frames = []

    # Try all possible corner combinations
    for r1 in range(height):
        for c1 in range(width):
            if grid[r1][c1] != color:
                continue
            for r2 in range(r1+1, height):
                for c2 in range(c1+1, width):
                    # Check if opposite corner exists
                    if grid[r2][c2] != color:
                        continue

                    # Must have at least 2 opposite corners
                    # Now check other corners
                    other_corners_exist = 0
                    if grid[r1][c2] == color:
                        other_corners_exist += 1
                    if grid[r2][c1] == color:
                        other_corners_exist += 1

                    if other_corners_exist == 2:
                        # We have all 4 corners
                        frames.append((r1, c1, r2, c2, True))
                    elif other_corners_exist >= 1:
                        # We have 3 corners or diagonal corners
                        frames.append((r1, c1, r2, c2, False))

    return frames, grid

