                if (cr, cc) in visited or grid[cr][cc] != val:
                    continue
                visited.add((cr, cc))
                cells.append((cr, cc))

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == val:
